'use strict';

const WebSocket = require('ws');
const Session = require('express-session').Session;
const jwtRefresh = require('../passport/jwt-refresh');

const GENERAL_WS_ERROR_CODE = 1008;

module.exports = ConnectionHandler;

function ConnectionHandler(loggingContext) {
  this.logger = loggingContext.getLogger('/approuter/WebSockets');
  this.tracer = loggingContext.getTracer(__filename);
}

function refreshJWT(req) {
  if (req.session && req.session.user && !req.session.jwtRefreshStarted) {
    jwtRefresh.refreshToken(req.app, req.session);
  }
}

ConnectionHandler.prototype.onOpen = function (incoming, outgoing) {
  let req = incoming.upgradeReq;
  this.memoryStore = req.app.get('memoryStore');
  if (req.session) {
    this.sessionID = req.session.id;
    refreshJWT(req);
  }
  this.incoming = incoming;
  this.outgoing = outgoing;

  if (this.sessionID) {
    let handleSessionEndFn = handleSessionEnd.bind(this);
    req.app.approuter.on('logout', handleSessionEndFn);
    incoming.on('close', function () {
      req.app.approuter.removeListener('logout', handleSessionEndFn);
    });
  }
  incoming.on('error', function (err) {
    resumeSource('outgoing');
    handleError.call(self, 'incoming', err);
  });
  outgoing.on('error', function (err) {
    resumeSource('incoming');
    handleError.call(self, 'outgoing', err);
  });
  let self = this;

  // paused flags track whether each source's TCP socket was paused for backpressure
  const paused = { incoming: false, outgoing: false };

  function resumeSource(sourceKey) {
    if (paused[sourceKey]) {
      paused[sourceKey] = false;
      paused._loggedBackpressure = false; // reset so next backpressure event is logged
      const src = self[sourceKey];
      const tcpSocket = src && src._socket;
      tcpSocket && tcpSocket.resume && tcpSocket.resume();
    }
  }

  // Wire drain events on the destination TCP sockets so resume fires reliably
  const outgoingTcp = outgoing._socket;
  if (outgoingTcp) {
    outgoingTcp.on('drain', function () { resumeSource('incoming'); });
  }
  const incomingTcp = incoming._socket;
  if (incomingTcp) {
    incomingTcp.on('drain', function () { resumeSource('outgoing'); });
  }

  incoming.on('message', function (msg, isBinary) {
    sendMessage.call(self, outgoing, msg, isBinary, incoming, 'incoming', paused);
    resetSessionTimeout.call(self, req);
  });
  outgoing.on('message', function (msg, isBinary) {
    sendMessage.call(self, incoming, msg, isBinary, outgoing, 'outgoing', paused);
  });
  incoming.on('close', function (code, message) {
    resumeSource('outgoing'); // unblock outgoing→incoming direction if paused
    handleClose.call(self, 'incoming', code, message);
  });
  outgoing.on('close', function (code, message) {
    resumeSource('incoming'); // unblock incoming→outgoing direction if paused
    handleClose.call(self, 'outgoing', code, message);
  });
  incoming.on('ping', resetSessionTimeout.bind(this, req));
  incoming.on('pong', handleIncomingPong.bind(this));
  outgoing.on('pong', incoming.pong.bind(incoming));
};

function resetSessionTimeout(req) {
  if (!this.sessionID) {
    return;
  }
  this.memoryStore.resetSessionTimer(this.sessionID);
  if (req.isSessionReloadStarted) {
    return;
  }
  req.isSessionReloadStarted = true;
  if (!isSocketOpen(this.incoming) || !isSocketOpen(this.outgoing)) {
    return;
  }
  this.memoryStore.get(this.sessionID, function (err, sess) {
    req.session = new Session(req, sess);
    refreshJWT(req);
  });
  setTimeout(function () {
    if (req) {
      req.isSessionReloadStarted = false;
    }
  }, 10 * 1000); // 10 seconds
}

function handleSessionEnd(session) {
  if (!session) {
    this.tracer.warn('[websockets] handleSessionEnd called without session argument, ignoring');
    return;
  }
  if (isSocketOpen(this.incoming) && session.id === this.sessionID) {
    this.tracer.debug('[websockets] session ended, closing incoming socket, session id: %s', session.id);
    this.incoming.close(GENERAL_WS_ERROR_CODE, 'Session ended!');
    this.sessionID = null;
  }
}

function handleIncomingPong(data) {
  resetSessionTimeout.call(this, this.incoming.upgradeReq);
  this.outgoing.pong(data, true, () => {
    return;
  });
}

function handleError(socketType, err) {
  this.logger.error(err, '[websockets] %s connection error occurred', socketType);
  let secondSocket = this[getSecondSocketType(socketType)];
  isSocketOpen(secondSocket) && secondSocket.close(GENERAL_WS_ERROR_CODE, err.message);
}

const BACKPRESSURE_THRESHOLD = parseInt(process.env.WS_BACKPRESSURE_THRESHOLD_BYTES, 10) || (4 * 1024 * 1024); // default 4 MB, tunable via env var

function sendMessage(socket, msg, isBinary, source, sourceKey, paused) {
  if (!isSocketOpen(socket)) {
    return this.logger.error('[websockets] cannot send message! Socket closed!');
  }
  let self = this;
  if (source && !paused[sourceKey] && socket.bufferedAmount >= BACKPRESSURE_THRESHOLD) {
    paused[sourceKey] = true;
    const tcpSocket = source._socket;
    tcpSocket && tcpSocket.pause && tcpSocket.pause();
    // Log at info level on first activation per connection so operators can see backpressure in production.
    // Note: if perMessageDeflate is negotiated, ws.bufferedAmount includes both the TCP write buffer and the
    // compressor queue. The TCP drain event fires when only the TCP component drops to zero, so it is possible
    // for resumeSource() to fire, a new message to re-trigger backpressure immediately, and the system to
    // self-correct on the next drain. This is correct — no data is lost, but it may produce additional info
    // log lines. Keep per-message noise at debug.
    if (!paused._loggedBackpressure) {
      paused._loggedBackpressure = true;
      self.logger.info('[websockets] backpressure activated: paused %s (bufferedAmount=%d, threshold=%d)', sourceKey, socket.bufferedAmount, BACKPRESSURE_THRESHOLD);
    }
    self.tracer.debug('[websockets] backpressure: paused %s (bufferedAmount=%d)', sourceKey, socket.bufferedAmount);
  }
  socket.send(msg, { binary: isBinary }, function ack(err) {
    if (err) {
      self.logger.error(err, '[websockets] error during socket.send');
    }
    // Resume is handled by the drain event on socket._socket, not here.
    // The send ack fires when the ws frame is queued into the OS buffer, not when it is consumed by the peer.
  });
}

function handleClose(socketType, code, message) {
  if (Buffer.isBuffer(message)) {
    message = message.length > 0 ? message.slice(0, 123).toString() : null;
  }
  message = message || (socketType + ' connection closed');
  code = (isValidCode(code) && code) || GENERAL_WS_ERROR_CODE;
  this.tracer.debug('[websockets] %s socket closed: %s, code: %d', socketType, message, code);
  let secondSocket = this[getSecondSocketType(socketType)];
  isSocketOpen(secondSocket) && secondSocket.close(code, message);
}

function isSocketOpen(socket) {
  return !!socket && socket.readyState === WebSocket.OPEN;
}

function isValidCode(code) {
  // the codes are defined in rfc6455#section-7.4
  return !!code && ((code >= 1000 && code <= 1011 && code !== 1004 && code !== 1005 && code !== 1006) ||
    (code >= 3000 && code <= 4999));
}

function getSecondSocketType(socketType) {
  return socketType === 'incoming' ? 'outgoing' : 'incoming';
}
